function supplierForm(sid){const s=W.state.suppliers.find(s=>s.id===sid);openModal('Supplier',field('Supplier name','name','text',s?.name||'','','required')+field('Contact details','contact','text',s?.contact||'')+field('Lead time (days)','lead','number',s?.leadDays||0,'','min="0" max="365" step="1"'),()=>mutate('supplier',{id:s?.id,name:value('name'),contact:value('contact'),leadDays:num('lead')}))}
function recipeForm(rid){if(!ensureProducts())return;const r=W.state.recipes.find(r=>r.id===rid);openModal(r?'Edit recipe':'Add recipe',field('Recipe name','name','text',r?.name||'','','required')+select('Recipe type','type',[['sale','Sale / serving'],['batch','Preparation batch']],r?.type||'sale')+`<div id="recipe-lines"></div>${btn('+ Add ingredient','recipe-line','secondary full')}`+select('Batch output product (batch recipes only)','output',productOptions(),r?.output?.productId)+field('Batch yield (in output stock units)','yield','number',r?.output?r.output.quantity/1000:1,'','min="0.001" step="0.001"')+`<label class="check-label"><input id="confirmed" type="checkbox" ${r?.confirmed?'checked':''}> These quantities have been checked against our actual preparation.</label>`,()=>{const parts=[...document.querySelectorAll('.recipe-edit-line')].map(el=>({productId:el.querySelector('select').value,quantity:Number(el.querySelector('input').value)}));return mutate('recipe',{id:r?.id,name:value('name'),type:value('type'),parts,confirmed:$('#confirmed').checked,output:value('type')==='batch'?{productId:value('output'),quantity:num('yield')}:null})});(r?.parts||[{productId:W.state.products[0].id,quantity:1000}]).forEach(addRecipeLine)}
function addRecipeLine(part={productId:W.state.products[0].id,quantity:1000}){const el=document.createElement('div');el.className='recipe-edit-line';el.innerHTML=`<select aria-label="Ingredient">${productOptions().map(([id,n])=>`<option value="${id}" ${id===part.productId?'selected':''}>${esc(n)}</option>`).join('')}</select><input aria-label="Ingredient quantity in stock units" type="number" min="0.001" step="0.001" required value="${part.quantity/1000}">${btn('Remove','remove-line','link')}`;$('#recipe-lines').append(el)}
function useRecipe(rid){const r=W.state.recipes.find(r=>r.id===rid);openModal(r.type==='batch'?'Prepare a batch':'Record recipe sale',`<h3>${esc(r.name)} · v${r.version}</h3><p class="sub">${r.confirmed?'Confirmed quantities':'Estimated quantities — practice use only'}</p>`+select('Stock location','location',locationOptions(),activeLocation)+field(r.type==='batch'?'Number of batches':'Number of servings','amount','number',1,'','required min="1" max="1000" step="1"')+(r.type==='batch'?field('Use-by date (optional, enter your assessed date)','useby','date')+field('Batch label / note','note'):'<p class="sub">Manual sale only. Do not also record this as a direct stock sale.</p>'),()=>mutate(r.type==='batch'?'prepare':'sale',{recipeId:r.id,locationId:value('location'),quantity:num('amount'),useBy:r.type==='batch'?value('useby'):'',note:r.type==='batch'?value('note'):''}),'Confirm & deduct ingredients')}
function receive(orderId){if(!ensureProducts())return;deliveryPhotos=[];deliveryPhotoBusy=0;const order=orderId?W.state.orders.find(o=>o.id===orderId):null;openModal(order?'Receive '+order.number:'Receive a delivery',`<div class="photo-note"><strong>Count boxes, not individual cans.</strong><p>Photos are stored as reference. Automatic reading is not connected. Check flavours and pack sizes before confirming.</p></div><div class="photo-actions">${btn('Take a photo','camera','secondary')}${btn('Choose photos','gallery','secondary')}</div><input type="file" id="camera-file" accept="image/jpeg,image/png,image/webp" capture="environment" hidden><input type="file" id="gallery-file" accept="image/jpeg,image/png,image/webp" multiple hidden><div id="photo-list"></div><p id="photo-message" class="sub" role="status"></p>`+select('Receive into','receive-location',locationOptions(),activeLocation)+select('Supplier (optional)','receive-supplier',[['','No supplier selected'],...W.state.suppliers.map(s=>[s.id,s.name])],order?.supplierId)+field('Delivery note / invoice reference','reference')+`${order?'':`<label>Find saved barcode<input id="receive-barcode" type="text" autocomplete="off" placeholder="Type, paste or use a keyboard scanner"></label>${btn('Add barcode item','delivery-barcode','secondary full')}<p class="sub">Adds one pack using the saved pack size. Each repeat adds another line for review. Camera barcode scanning is not connected.</p>`}<div id="receive-lines" data-order="${order?.id||''}"></div>${order?'':btn('+ Add product / flavour','delivery-line','secondary full')}<div class="delivery-summary" id="receive-summary" aria-live="polite"></div>`,reviewDelivery,'Review delivery');if(order){$('#receive-supplier').disabled=true;order.lines.forEach((l,n)=>{if(l.received<l.quantity)addDeliveryLine({productId:l.productId,boxes:0,pack:pfind(l.productId).pack/1000,loose:(l.quantity-l.received)/1000,orderLine:n})})}}
function addDeliveryLine(line){const p=pfind(line?.productId)||W.state.products.find(p=>p.name.startsWith('Pringles'))||W.state.products[0],el=document.createElement('section');el.className='delivery-line';if(line?.orderLine!==undefined)el.dataset.orderLine=line.orderLine;el.innerHTML=`<div class="line-heading"><strong>Delivery item</strong>${btn('Remove','remove-delivery','link')}</div><div class="settings-actions">${btn('+1 box','delivery-box','small-btn')}${btn('8 boxes','delivery-eight','small-btn')}${btn('9 boxes','delivery-nine','small-btn')}</div><label>Product / flavour<select data-delivery-product ${line?.orderLine!==undefined?'disabled':''}>${productOptions().map(([id,n])=>`<option value="${id}" ${id===p.id?'selected':''}>${esc(n)}</option>`).join('')}</select></label><div class="pack-fields"><label>Boxes / packs<input data-boxes type="number" min="0" step="1" required value="${line?.boxes??1}"></label><label><span data-pack-label>${p.unit} per pack</span><input data-pack type="number" min="0.001" step="0.001" required value="${line?.pack??p.pack/1000}"></label><label><span data-loose-label>Loose ${p.unit}</span><input data-loose type="number" min="0" step="0.001" required value="${line?.loose??0}"></label></div><label>Actual purchase cost per ${p.unit} (£, optional)<input data-cost type="number" min="0" step="0.000001" placeholder="Leave blank if unknown"></label><p class="line-total" aria-live="polite"></p>`;$('#receive-lines').append(el);updateReceiving()}
function deliveryData(){return {locationId:value('receive-location'),supplierId:value('receive-supplier')||null,orderId:$('#receive-lines').dataset.order||null,reference:value('reference'),photos:deliveryPhotos.map(p=>p.id),lines:[...document.querySelectorAll('#receive-lines .delivery-line')].map(el=>({productId:el.querySelector('[data-delivery-product]').value,boxes:Number(el.querySelector('[data-boxes]').value),pack:Number(el.querySelector('[data-pack]').value),loose:Number(el.querySelector('[data-loose]').value),cost:el.querySelector('[data-cost]').value===''?null:Number(el.querySelector('[data-cost]').value),orderLine:el.dataset.orderLine===undefined?undefined:Number(el.dataset.orderLine)}))}}
function updateReceiving(){document.querySelectorAll('#receive-lines .delivery-line').forEach(el=>{const p=pfind(el.querySelector('select').value),boxes=Number(el.querySelector('[data-boxes]').value),pack=Number(el.querySelector('[data-pack]').value),loose=Number(el.querySelector('[data-loose]').value);el.querySelector('.line-total').textContent=`${fmt(boxes)} × ${fmt(pack)} + ${fmt(loose)} = ${fmt(boxes*pack+loose)} ${p.unit}`});$('#receive-summary').textContent=`${document.querySelectorAll('#receive-lines .delivery-line').length} lines · Stock is added only after confirmation.`}
function reviewDelivery(){if(deliveryPhotoBusy)throw Error('Wait for your photos to finish uploading.');const data=deliveryData();if(!data.lines.length)throw Error('Add at least one delivery item.');if(data.lines.some(l=>l.boxes*l.pack+l.loose<=0))throw Error('Each delivery line must have a positive total. Remove lines that did not arrive.');const savedHTML=$('#fields').innerHTML;const controls=[...$('#fields').querySelectorAll('input,select')].map(e=>e.value);const photos=deliveryPhotos.slice();const version=formVersion;openModal('Check delivery before saving',`<p class="sub">Into ${esc(lfind(data.locationId)?.name)} · ${data.reference?esc(data.reference):'No reference'}</p>`+data.lines.map(l=>`<section class="delivery-line"><h3>${esc(pfind(l.productId).name)}</h3><p>${l.boxes} boxes × ${fmt(l.pack)} + ${fmt(l.loose)} loose</p><b>Add ${fmt(l.boxes*l.pack+l.loose)} ${pfind(l.productId).unit}</b></section>`).join('')+`<p>${photos.length} saved reference photos</p>${btn('Back to edit','back-delivery','secondary full')}`,()=>mutate('delivery',data),'Confirm & add stock');formVersion=version;$('#fields [data-action="back-delivery"]').onclick=()=>{openModal('Receive a delivery',savedHTML,reviewDelivery,'Review delivery');[...$('#fields').querySelectorAll('input,select')].forEach((e,n)=>{if(e.type!=='file')e.value=controls[n]});deliveryPhotos=photos;formVersion=version;updateReceiving()}}
async function uploadPhotos(input){const files=[...input.files];input.value='';for(const file of files){if(deliveryPhotos.length>=12){$('#photo-message').textContent='Maximum 12 photos per delivery.';break}deliveryPhotoBusy++;$('#photo-message').textContent='Saving photo…';try{if(file.size>8*1024*1024)throw Error('Choose a photo under 8 MB.');const r=await api(wp('photo'),{method:'POST',headers:{'content-type':file.type},body:file});deliveryPhotos.push({id:r.id});if($('#photo-list')){$('#photo-list').innerHTML=deliveryPhotos.map(p=>`<figure><img src="/api/${wp('photo?id='+p.id)}" alt="Saved delivery reference"></figure>`).join('');$('#photo-message').textContent=`${deliveryPhotos.length} photos saved for this delivery.`}}catch(e){if($('#photo-message'))$('#photo-message').textContent=e.message}finally{deliveryPhotoBusy--}}}
function purchaseForm(){if(!ensureProducts())return;if(!W.state.suppliers.length)return toast('Add a supplier first.');openModal('Create purchase order',select('Supplier','supplier',W.state.suppliers.map(s=>[s.id,s.name]))+`<div id="purchase-lines"></div>${btn('+ Add product','purchase-line','secondary full')}<p class="sub">Creates a draft. No order is sent to the supplier.</p>`,()=>mutate('purchase',{supplierId:value('supplier'),lines:[...document.querySelectorAll('.purchase-line')].map(el=>({productId:el.querySelector('select').value,quantity:Number(el.querySelector('[data-po-quantity]').value),cost:el.querySelector('[data-po-cost]').value===''?null:Number(el.querySelector('[data-po-cost]').value)}))}),'Save draft order');addPurchaseLine()}
function addPurchaseLine(){const el=document.createElement('section');el.className='purchase-line delivery-line';el.innerHTML=`<label>Product<select>${productOptions().map(([id,n])=>`<option value="${id}">${esc(n)}</option>`).join('')}</select></label><label>Quantity in stock units<input data-po-quantity type="number" min="0.001" step="0.001" required></label><label>Expected unit purchase cost (£, optional)<input data-po-cost type="number" min="0" step="0.000001"></label>${btn('Remove','remove-line','link')}`;$('#purchase-lines').append(el)}
function viewOrder(oid){const o=W.state.orders.find(o=>o.id===oid);openModal(o.number+' · '+o.status,`<p>${esc(W.state.suppliers.find(s=>s.id===o.supplierId)?.name)}</p>`+o.lines.map(l=>`<section class="delivery-line"><h3>${esc(pfind(l.productId).name)}</h3><p>Ordered: ${fmt(l.quantity/1000)} ${pfind(l.productId).unit} · Received: ${fmt(l.received/1000)}</p><p>Expected unit cost: ${money(l.costMicro)}</p></section>`).join('')+`<div class="settings-actions">${canManage()&&o.status==='draft'?btn('Mark as placed externally','place-order','primary',`data-id="${o.id}"`):''}${canWrite()&&['ordered','partial'].includes(o.status)?btn('Receive against order','receive-order','primary',`data-id="${o.id}"`):''}${canManage()&&['draft','ordered'].includes(o.status)&&o.lines.every(l=>l.received===0)?btn('Cancel order','cancel-order','secondary',`data-id="${o.id}"`):''}</div><p class="sub">Invoices and supplier orders are handled externally in this release.</p>`,null)}
async function team(){const r=await api(wp('team'));openModal('Business team',r.members.map(m=>`<div class="delivery-line"><h3>${esc(m.email)}</h3><p>${esc(m.role)}</p>${W.role==='owner'&&m.role!=='owner'?`<select aria-label="New role for ${esc(m.email)}" data-member="${esc(m.user_id)}">${['manager','staff','viewer','remove'].map(role=>`<option value="${role}" ${role===m.role?'selected':''}>${role}</option>`).join('')}</select>${btn('Apply role','member-role','secondary full',`data-id="${esc(m.user_id)}"`)}`:''}</div>`).join(''),null)}
function createWorkspace(){const createId=crypto.randomUUID();openModal('Create a business',field('Business name','name','text','Bouldr Bar','','required maxlength="100"')+select('Starting data','mode',[['real','Real business — empty stock'],['demo','Practice — example stock and recipes']])+`<p class="sub">Business records are separate. Nothing is shared with another business automatically.</p>`,async()=>{const r=await api('workspaces',{method:'POST',body:JSON.stringify({name:value('name'),demo:value('mode')==='demo',requestId:createId})});$('#modal').close();boot=await api('bootstrap');await loadWorkspace(r.id)},'Create business')}
function joinWorkspace(){openModal('Join a business',field('Single-use access code','code','text','','','required')+`<p class="sub">You must also be allowed to open this private Site. Ask the owner if access is blocked.</p>`,async()=>{const r=await api('join',{method:'POST',body:JSON.stringify({code:value('code')})});$('#modal').close();boot=await api('bootstrap');await loadWorkspace(r.id)},'Join business')}
function invite(){openModal('Create a staff access code',select('Role','role',[['staff','Staff — receive, count, waste, transfer and record sales'],['manager','Manager — stock, recipes, suppliers and purchasing'],['viewer','Viewer — read-only records']])+`<p class="sub">One use, expires in 24 hours. You decide who receives it. Creating a code does not send a message.</p>`,async()=>{const r=await api(wp('invite'),{method:'POST',body:JSON.stringify({role:value('role')})});openModal('Staff access code',`<p>Share this code with your chosen staff member.</p><textarea readonly aria-label="Staff access code">${esc(r.code)}</textarea><p class="sub">Expires ${date(r.expiresAt)}. The person also needs access through the Site’s sharing controls.</p>`,null)},'Create code')}
async function exportRecords(){const data=await api(wp('export'));const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bouldr-stock-records-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Records exported. Photo files are not included.')}
async function handleAction(action,id,el){if(action==='close'){if(!busy&&!deliveryPhotoBusy)$('#modal').close();return}if(action==='refresh'){if($('#modal').open)return toast('Finish or close your current entry first.');await reload();toast('Latest stock loaded.');return}if(action==='retry-start')return start();if(action==='switch-workspace')return openModal('Switch business',select('Business','business',boot.workspaces.map(w=>[w.id,w.name]),W.id),async()=>{const id=value('business');$('#modal').close();await loadWorkspace(id)},'Open business');if(action==='create-workspace')return createWorkspace();if(action==='join-workspace')return joinWorkspace();if(action==='product')return productForm(id);if(action==='receive')return receive();if(action==='waste')return movementForm('waste');if(action==='transfer')return movementForm('transfer');if(action==='unit-sale')return movementForm('unit_sale');if(action==='supplier')return supplierForm(id);if(action==='recipe')return recipeForm(id);if(action==='recipe-line')return addRecipeLine();if(action==='remove-line'){el.closest('.recipe-edit-line,.purchase-line').remove();return}if(action==='use-recipe')return useRecipe(id);if(action==='location')return openModal('Add stock location',field('Location name','name','text','','e.g. Main bar, kitchen, cellar','required'),()=>mutate('location',{name:value('name')}));if(action==='camera')return $('#camera-file').click();if(action==='gallery')return $('#gallery-file').click();if(action==='delivery-barcode'){const code=value('receive-barcode').trim();if(!code)throw Error('Enter a saved barcode first.');const matches=W.state.products.filter(p=>p.barcode&&p.barcode.trim()===code);if(matches.length!==1)throw Error(matches.length?'This barcode matches more than one product. Choose the correct flavour manually.':'Barcode not found. Add the product manually and save its barcode in Stock.');addDeliveryLine({productId:matches[0].id});$('#receive-barcode').value='';$('#receive-barcode').focus();return}if(['delivery-box','delivery-eight','delivery-nine'].includes(action)){const input=el.closest('.delivery-line').querySelector('[data-boxes]');input.value=action==='delivery-box'?Number(input.value)+1:action==='delivery-eight'?8:9;updateReceiving();return}if(action==='delivery-line')return addDeliveryLine();if(action==='remove-delivery'){el.closest('.delivery-line').remove();updateReceiving();return}if(action==='purchase')return purchaseForm();if(action==='purchase-line')return addPurchaseLine();if(action==='view-order')return viewOrder(id);if(action==='receive-order')return receive(id);if(action==='place-order'||action==='cancel-order'){const status=action==='place-order'?'ordered':'cancelled';return openModal(status==='ordered'?'Confirm order was placed':'Cancel purchase order',`<p>${status==='ordered'?'Confirm that you have placed this order with the supplier outside this app.':'This cancels an unreceived order. It does not contact the supplier.'}</p>`,()=>mutate('order_status',{orderId:id,status}),'Confirm')}if(action.startsWith('sq-'))return squareAction(action,id,el);if(action==='alerts')return alertsPanel();if(action==='alerts-config')return alertsConfig();if(action==='alerts-check')return openModal('Queue a stock reminder','<p>This checks current stock and queues an email to the configured handler if alerts are enabled and the 24-hour cooldown has passed. Practice workspaces never send.</p>',()=>mutate('notification_check',{}),'Check & queue reminder');if(action==='alerts-retry'){const r=await api(wp('notifications/retry'),{method:'POST',body:'{}'});toast(r.sent+' emails accepted by the provider.');return alertsPanel()}if(action==='team')return team();if(action==='invite')return invite();if(action==='member-role'){const role=[...document.querySelectorAll('[data-member]')].find(x=>x.dataset.member===id).value;return openModal('Confirm staff access change',`<p>Set this member’s access to ${esc(role)}?</p>`,async()=>{await api(wp('member'),{method:'POST',body:JSON.stringify({userId:id,role})});$('#modal').close();await reload()},'Confirm access change')}if(action==='export')return exportRecords();if(action==='more-history'){const r=await api(wp('history?before='+historyNext));history.push(...r.events);historyNext=r.next;render();return}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;if(action==='back-delivery')return;try{await handleAction(action,el.dataset.id,el)}catch(error){if($('#modal').open)$('#form-error').textContent=error.message;else toast(error.message)}});
document.addEventListener('input',e=>{if(['stock-search','stock-category','stock-filter'].includes(e.target.id))stockTable();if(e.target.closest('#receive-lines'))updateReceiving()});
document.addEventListener('change',async e=>{try{if(e.target.id==='workspace-select'){if(busy)return;await loadWorkspace(e.target.value)}if(e.target.id==='location-select'){activeLocation=e.target.value;render()}if(['camera-file','gallery-file'].includes(e.target.id))await uploadPhotos(e.target);if(e.target.matches('[data-delivery-product]')){const el=e.target.closest('.delivery-line'),p=pfind(e.target.value);el.querySelector('[data-pack]').value=p.pack/1000;el.querySelector('[data-pack-label]').textContent=p.unit+' per pack';el.querySelector('[data-loose-label]').textContent='Loose '+p.unit;updateReceiving()}}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{if(e.target.id==='receive-barcode'&&e.key==='Enter'){e.preventDefault();try{handleAction('delivery-barcode').catch(err=>$('#form-error').textContent=err.message)}catch(err){$('#form-error').textContent=err.message}}});
$('#form').onsubmit=submitModal;$('#modal').addEventListener('cancel',e=>{if(busy||deliveryPhotoBusy)e.preventDefault()});window.addEventListener('hashchange',render);start();
let squareInbox=[],squareConnection=false,squareEnvironment=null,squareCursor=null,squareQuery=null;
const sqcfg=()=>W.state.square||{catalog:[],rules:[],locations:{},cutover:null};
function squarePage(){if(!canManage())return pageTitle('Till integration','Square','A manager can configure sales and stock rules.')+'<div class="notice">Ask a manager to review the Square connection.</div>';const cfg=sqcfg();return pageTitle('From till to stockroom','Square, with stock control.','Match each serving and modifier to the stock it actually uses.')+`<div class="square-hero"><div><span class="square-status" id="sq-connection">Checking connection…</span><h2>One sale. The right deduction.</h2><p>Read Square sales, review exceptions, then apply stock changes.</p></div>${btn('Connection setup','sq-setup','secondary')}</div><div class="square-actions">${btn('Match a till item','sq-rule')}${btn('Map a location','sq-config','secondary')}${btn('Import catalogue','sq-catalogue','secondary')}${btn('Fetch sales','sq-fetch','secondary')}${W.state.demo?btn('Load practice cases','sq-examples','secondary'):''}</div><div class="scenario-grid">${[['Pints & halves','One keg product, separate 568 ml and 284 ml rules.'],['Cocktails & doubles','Match the exact variation and modifiers to an agreed recipe.'],['Cans & bottles','Deduct one stock unit for each item sold.'],['Refunds & voids','Cancelled and refunded orders stay out of automatic deductions.'],['Extras & substitutions','Unknown modifiers are held for review, never silently ignored.'],['Vouchers & discounts','Mark non-stock items explicitly. Discounts do not change quantities.']].map(([t,d])=>`<article><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Sales inbox</h2>${btn('Refresh inbox','sq-refresh','small-btn')}</div><div id="sq-inbox"><p class="empty">Loading saved orders…</p></div><div class="settings-actions" id="sq-next"></div></section><section class="panel"><div class="panel-head"><h2>Stock rules</h2><span class="badge">${cfg.rules.length} rules</span></div>${cfg.rules.map((r,n)=>`<div class="square-rule"><div class="line-heading"><b>${esc(r.label)}</b>${btn('Edit','sq-rule','small-btn',`data-id="${n}"`)}</div><p>${r.type==='product'?fmt(r.quantity/1000)+' '+esc(pfind(r.targetId)?.unit)+' '+esc(pfind(r.targetId)?.name):r.type==='recipe'?'Recipe: '+esc(W.state.recipes.find(x=>x.id===r.targetId)?.name):'No stock: '+esc(r.note)}</p><small>${esc(r.variationId)}${r.modifiers.length?' · modifiers: '+esc(r.modifiers.join(', ')):' · no modifiers'}</small></div>`).join('')||'<p class="empty">Add a rule for each serving size or modifier combination.</p>'}</section><div class="notice">Sales imports are manager-controlled, not a live automatic sync. Set the start date after an opening count and reconcile any manual sales first. Orders can arrive late from offline tills. Recipe deductions use the version reviewed when you apply the order; refunds after application require a manual stock decision.</div>`}
async function loadSquareStatus(){try{const r=await api(wp('square/status'));squareInbox=r.orders;squareConnection=r.configured;squareEnvironment=r.environment;if($('#sq-connection'))$('#sq-connection').textContent=r.configured?'Credential configured · '+r.environment:'Not connected · practice and mapping available';drawSquareInbox()}catch(e){if($('#sq-inbox'))$('#sq-inbox').innerHTML=`<p class="empty">${esc(e.message)}</p>`}}
function drawSquareInbox(){if(!$('#sq-inbox'))return;$('#sq-inbox').innerHTML=squareInbox.map((o,n)=>`<div class="stock-row"><div class="item-info"><strong>${esc(o.payload.lines.map(l=>l.name).join(', '))}</strong><small>${esc(o.order_id)} · ${o.payload.source==='practice'?'Practice example':'Square order'} · ${esc(o.payload.state)}</small><small>${o.status==='applied'?'Applied once · stock updated':o.status==='review'?'Order changed after application · review required':o.plan.ready?'Ready to review':esc(o.plan.problems[0])}</small></div>${btn('Review','sq-review','small-btn',`data-id="${n}"`)}</div>`).join('')||'<p class="empty">No imported orders. Connect Square or load cases in a practice workspace.</p>';$('#sq-next').innerHTML=squareCursor?btn('Fetch next page','sq-next-page','secondary'):''}
function sqRuleForm(index){if(!ensureProducts())return;const r=index!==undefined?sqcfg().rules[Number(index)]:null;openModal('Match a Square sale',select('Catalogue reference (optional)','sq-catalogue-choice',[['','Enter IDs manually'],...sqcfg().catalog.map(c=>[c.variationId,c.itemName+' · '+c.variationName])],r?.variationId)+field('Rule label','sq-label','text',r?.label||'','','required')+field('Square variation ID','sq-variation','text',r?.variationId||'','','required')+field('Exact modifier IDs, comma-separated (blank means none)','sq-modifiers','text',r?.modifiers.join(', ')||'')+select('Stock action','sq-type',[['product','Deduct a stock product'],['recipe','Use a sale recipe'],['ignore','No physical stock movement']],r?.type||'product')+select('Stock product','sq-product',productOptions(),r?.targetId)+field('Stock units deducted per sale','sq-quantity','number',r?.type==='product'?r.quantity/1000:1,'','min="0.001" step="0.001"')+select('Sale recipe','sq-recipe',W.state.recipes.filter(r=>r.type==='sale').map(r=>[r.id,r.name]),r?.targetId)+field('Explanation for no-stock rules','sq-note','text',r?.note||'')+`<p class="sub">For double cocktails, use an appropriate double-shot recipe. The app does not assume every ingredient doubles.</p>`,()=>mutate('square_rule',{label:value('sq-label'),variationId:value('sq-variation'),modifiers:value('sq-modifiers').split(',').map(s=>s.trim()).filter(Boolean),type:value('sq-type'),targetId:value('sq-type')==='recipe'?value('sq-recipe'):value('sq-type')==='product'?value('sq-product'):null,quantity:num('sq-quantity'),note:value('sq-note')}));$('#sq-catalogue-choice').onchange=()=>{const c=sqcfg().catalog.find(c=>c.variationId===value('sq-catalogue-choice'));if(c){$('#sq-variation').value=c.variationId;$('#sq-label').value=c.itemName+' · '+c.variationName}}}
function sqConfigForm(){openModal('Square location & start date',field('Square location ID','sq-location','text','','From the Square location list','required')+select('Deduct stock from','sq-stock-location',locationOptions(),activeLocation)+field('Sync start (UTC)','sq-cutover','datetime-local',sqcfg().cutover?.slice(0,16)||'')+`<label class="check-label"><input id="sq-count-ready" type="checkbox" required>I will only import sales after the opening count, and will reconcile manual sales to avoid counting them twice.</label>${btn('Read connected Square locations','sq-locations','secondary full')}<div id="sq-location-list"></div>`,()=>mutate('square_config',{squareLocationId:value('sq-location'),locationId:value('sq-stock-location'),cutover:value('sq-cutover')?value('sq-cutover')+':00Z':null}),'Save mapping')}
function sqFetchForm(){if(!squareConnection)return squareAction('sq-setup');const mapped=Object.keys(sqcfg().locations);if(!mapped.length)return toast('Map a Square location first.');openModal('Fetch Square sales',select('Square location','sq-fetch-location',mapped.map(id=>[id,id+' → '+lfind(sqcfg().locations[id])?.name]))+field('Updated from (UTC)','sq-from','datetime-local',new Date(Date.now()-86400000).toISOString().slice(0,16),'','required')+field('Updated until (UTC)','sq-until','datetime-local',new Date().toISOString().slice(0,16),'','required')+'<p class="sub">Up to 7 days per search, 100 orders per page. Fetching saves orders to the inbox; it does not deduct stock.</p>',async()=>{squareQuery={locationId:value('sq-fetch-location'),start:value('sq-from')+':00Z',end:value('sq-until')+':00Z'};const r=await api(wp('square/orders'),{method:'POST',body:JSON.stringify(squareQuery)});squareCursor=r.cursor;$('#modal').close();await loadSquareStatus();toast(r.count+' orders fetched into the inbox.')},'Fetch for review')}
async function squareAction(action,index){if(action==='sq-setup')return openModal('Square connection setup',`<h3>${squareConnection?'Server credential configured':'Square account connection needed'}</h3><p>The prepared reader can retrieve catalogue variations, locations and orders. It cannot take payments, issue refunds or change your Square stock.</p><ol class="square-list"><li>The bar owner authorises access to the Square account.</li><li>Configure the credential securely for this business, with item, location and order read access.</li><li>Import the catalogue, map locations and set serving/recipe rules.</li><li>Take an opening count, choose a sync start, then review a small sales window.</li></ol><p class="sub">No credential entry in this page. Multi-business OAuth onboarding and background webhook syncing are not implemented yet.</p>`,null);if(action==='sq-rule')return sqRuleForm(index);if(action==='sq-config')return sqConfigForm();if(action==='sq-refresh')return loadSquareStatus();if(action==='sq-fetch')return sqFetchForm();if(action==='sq-locations'){const r=await api(wp('square/locations'));$('#sq-location-list').innerHTML=r.locations.map(l=>`<p><b>${esc(l.name)}</b><br>${esc(l.id)} · ${esc(l.status)}</p>`).join('');return}if(action==='sq-examples'){if(!W.state.demo)return;openModal('Load Square practice cases','<p>Add example rules and seven practice orders. These never contact Square or affect a real workspace.</p>',async()=>{await mutate('square_examples',{});await api(wp('square/orders'),{method:'POST',body:JSON.stringify({examples:true})});await loadSquareStatus()},'Load practice cases');return}if(action==='sq-catalogue'){if(!squareConnection)return squareAction('sq-setup');openModal('Import Square catalogue references','<p>This reads names and variation IDs for mapping. It does not replace products or quantities in your stockroom.</p>',async()=>{let cursor=null,catalog=[],pages=0;do{const r=await api(wp('square/catalogue'),{method:'POST',body:JSON.stringify({cursor})});catalog.push(...r.catalog);cursor=r.cursor;pages++;if(pages>=20&&cursor)throw Error('Catalogue exceeds the supported import size. No references saved.');}while(cursor);await mutate('square_catalog',{catalog})},'Read catalogue');return}if(action==='sq-next-page'){const r=await api(wp('square/orders'),{method:'POST',body:JSON.stringify({...squareQuery,cursor:squareCursor})});squareCursor=r.cursor;await loadSquareStatus();return}if(action==='sq-review'){const o=squareInbox[Number(index)],plan=o.plan;openModal('Review Square order',`<p><b>${esc(o.order_id)}</b> · ${esc(o.payload.state)} · ${esc(o.status)}</p>${o.status==='review'?'<div class="review-warning">This order changed after stock was deducted. Compare the saved history and make an explicit count correction if necessary. No second automatic deduction is allowed.</div>':''}${plan.problems.map(p=>`<div class="review-warning">${esc(p)}</div>`).join('')}<h3>Proposed stock use</h3>${plan.deductions.map(d=>`<p>${esc(pfind(d.productId)?.name)}: −${fmt(d.quantity/1000)} ${pfind(d.productId)?.unit}</p>`).join('')||'<p>No physical stock deductions.</p>'}<p class="sub">Only confirm if this sale has not already been recorded manually. The current reviewed recipe versions are saved with the change.</p>`,o.status==='pending'&&plan.ready?()=>mutate('square_apply',{orderId:o.order_id}):null,'Confirm & apply once');return}}

let alertState;
async function alertsPanel(){alertState=await api(wp('notifications'));openModal('Low-stock messages',`<div class="notice">${alertState.configured?'Email provider configured':'Email service not connected yet. Messages cannot be sent.'}</div><p><b>Stock handler:</b> ${esc(alertState.settings.recipient||'Not set')}</p><p>Automatic alerts: ${alertState.settings.enabled?'Enabled':'Off'}</p><p class="sub">Checks run after saved stock changes, with at most one reorder email every 24 hours. There is no scheduled daily check while the app is idle. Practice workspaces never send.</p><div class="settings-actions">${W.role==='owner'?btn('Set recipient & alerts','alerts-config','primary'):''}${btn('Check current stock','alerts-check','secondary')}${btn('Retry queued messages','alerts-retry','secondary')}</div><h3>Message history</h3>${alertState.messages.map(m=>`<div class="delivery-line"><b>${esc(m.subject)}</b><p>${esc(m.recipient)} · ${esc(m.status)}</p><small>${date(m.created_at)} ${esc(m.error||'')}</small></div>`).join('')||'<p class="sub">No messages queued.</p>'}<p class="sub">“Accepted” means the email provider accepted the request; it does not confirm inbox delivery or that the message was read.</p>`,null)}
function alertsConfig(){const c=alertState?.settings||{recipient:'',enabled:false};openModal('Stock-handler email',field('Stock handler email address','alert-email','email',c.recipient,'','required')+`<label class="check-label"><input id="alert-confirm" type="checkbox" required>I have checked this is the correct stock handler and authorise reorder reminders to this address.</label><label class="check-label"><input id="alert-enabled" type="checkbox" ${c.enabled?'checked':''}>Enable automatic low-stock emails</label><p class="sub">Saving with alerts enabled can queue the first low-stock message. Sending requires a connected email service. No purchase is made.</p>`,()=>mutate('notification_config',{recipient:value('alert-email'),confirmed:$('#alert-confirm').checked,enabled:$('#alert-enabled').checked}),'Save alert settings')}
